// DriverServiceServer is the server API for DriverService service.
// All implementations must embed UnimplementedDriverServiceServer
// for forward compatibility.
type DriverServiceServer interface {
	// ExportPersonalData returns what this service keeps about one person,
	// for their "Download your data" file. Internal only (identity-service).
	ExportPersonalData(context.Context, *v1.ExportPersonalDataRequest) (*v1.ExportPersonalDataResponse, error)
	// GetDriverSupply counts drivers by status, availability and class right
	// now, for the business reports (analytics). Internal only.
	GetDriverSupply(context.Context, *GetDriverSupplyRequest) (*GetDriverSupplyResponse, error)
	// CreateDriver creates the caller's own driver profile: identity_id must be the caller's identity.
	// The new driver starts PENDING and cannot go online until an operator approves it.
	CreateDriver(context.Context, *CreateDriverRequest) (*CreateDriverResponse, error)
	// GetDriver returns the caller's own driver profile.
	GetDriver(context.Context, *GetDriverRequest) (*GetDriverResponse, error)
	// GetDriverByIdentity finds the caller's driver profile from their identity id.
	GetDriverByIdentity(context.Context, *GetDriverByIdentityRequest) (*GetDriverResponse, error)
	// UpdateDriverProfile changes the caller's own driver profile and vehicle.
	// Once approved, the name and the vehicle can no longer be changed this way
	// (FAILED_PRECONDITION).
	UpdateDriverProfile(context.Context, *UpdateDriverProfileRequest) (*UpdateDriverProfileResponse, error)
	// UpdateAvailability goes online or offline; only the driver themselves may.
	// A PENDING or REJECTED driver may only be offline (FAILED_PRECONDITION otherwise).
	// Going AVAILABLE also needs every required document approved and in date
	// (FAILED_PRECONDITION); a BUSY driver who is not is put OFFLINE instead.
	UpdateAvailability(context.Context, *UpdateAvailabilityRequest) (*UpdateAvailabilityResponse, error)
	// ApproveDriver moves a PENDING (or REJECTED) driver to ACTIVE. Staff with
	// drivers.approve, or the internal token. A driver can never approve themselves.
	// Every required document must be approved and in date (FAILED_PRECONDITION).
	ApproveDriver(context.Context, *ApproveDriverRequest) (*ApproveDriverResponse, error)
	// RejectDriver moves a PENDING driver to REJECTED, with the reason the driver
	// is shown. Staff with drivers.approve, or the internal token.
	RejectDriver(context.Context, *RejectDriverRequest) (*RejectDriverResponse, error)
	// ListDrivers lists drivers for the review queue and the admin, newest first,
	// optionally by status. Staff with drivers.read, or the internal token.
	ListDrivers(context.Context, *ListDriversRequest) (*ListDriversResponse, error)
	// ListDriverDocumentTypes lists the documents a driver is asked for (the
	// active types), in the order the app shows them. Any signed-in user.
	ListDriverDocumentTypes(context.Context, *ListDriverDocumentTypesRequest) (*ListDriverDocumentTypesResponse, error)
	// AdminListDriverDocumentTypes lists every type, inactive ones too. Staff
	// with drivers.read, or the internal token.
	AdminListDriverDocumentTypes(context.Context, *ListDriverDocumentTypesRequest) (*ListDriverDocumentTypesResponse, error)
	// UpsertDriverDocumentType creates or changes a document type: whether it is
	// required, needs a number or an expiry date, and whether it is asked for at
	// all. Staff with drivers.configure, or the internal token.
	UpsertDriverDocumentType(context.Context, *UpsertDriverDocumentTypeRequest) (*DriverDocumentTypeResponse, error)
	// SubmitDriverDocument hands an uploaded file (media-service, READY, the
	// driver's own, of the type's purpose) in as a document, waiting for review.
	// It replaces an earlier pending or rejected one of the same type; an
	// approved one stays valid until the new one is approved.
	SubmitDriverDocument(context.Context, *SubmitDriverDocumentRequest) (*DriverDocumentResponse, error)
	// ListDriverDocuments shows, per document type, where the driver stands, and
	// whether they may work. The driver, or staff with drivers.read.
	ListDriverDocuments(context.Context, *ListDriverDocumentsRequest) (*ListDriverDocumentsResponse, error)
	// ListPendingDriverDocuments is the review queue, oldest first. Staff with
	// drivers.read, or the internal token.
	ListPendingDriverDocuments(context.Context, *ListPendingDriverDocumentsRequest) (*ListPendingDriverDocumentsResponse, error)
	// ApproveDriverDocument approves a pending document; the reviewer may correct
	// the number and expiry date read from it. It replaces the driver's earlier
	// approved one of that type. Staff with drivers.approve, or the internal token.
	ApproveDriverDocument(context.Context, *ApproveDriverDocumentRequest) (*DriverDocumentResponse, error)
	// RejectDriverDocument turns down a pending document, or withdraws an
	// approved one (a driver who is online then goes offline), with the reason
	// the driver is shown. Staff with drivers.approve, or the internal token.
	RejectDriverDocument(context.Context, *RejectDriverDocumentRequest) (*DriverDocumentResponse, error)
	// AddVehicle registers another car for the driver. It waits for staff review
	// (and its documents) before it can be made active. At most 5 cars in service.
	AddVehicle(context.Context, *AddVehicleRequest) (*VehicleResponse, error)
	// ListVehicles lists the driver's cars, retired ones last. The driver, or
	// staff with drivers.read.
	ListVehicles(context.Context, *ListVehiclesRequest) (*ListVehiclesResponse, error)
	// UpdateVehicle corrects a car that is still pending or was rejected; a
	// rejected car goes back to review.
	UpdateVehicle(context.Context, *UpdateVehicleRequest) (*VehicleResponse, error)
	// ActivateVehicle makes an approved car the one the driver works with. The
	// driver must be offline.
	ActivateVehicle(context.Context, *VehicleActionRequest) (*VehicleResponse, error)
	// RetireVehicle takes a car out of service for good (sold, scrapped); its
	// documents go with it. The active car cannot be retired.
	RetireVehicle(context.Context, *VehicleActionRequest) (*VehicleResponse, error)
	// ListPendingVehicles is the car review queue, oldest first. Staff with
	// drivers.read, or the internal token.
	ListPendingVehicles(context.Context, *ListPendingVehiclesRequest) (*ListPendingVehiclesResponse, error)
	// ApproveVehicle approves a pending car once its required documents are
	// approved and in date; the reviewer may set its year and class. Staff with
	// drivers.approve, or the internal token.
	ApproveVehicle(context.Context, *ApproveVehicleRequest) (*VehicleResponse, error)
	// RejectVehicle turns down a pending car, with the reason the driver is
	// shown. Staff with drivers.approve, or the internal token.
	RejectVehicle(context.Context, *RejectVehicleRequest) (*VehicleResponse, error)
	// Details: gender, date of birth (18 or older) and nationality (ISO 3166
	// alpha-2). The driver's own (staff with drivers.read too).
	GetDriverDetails(context.Context, *GetDriverDetailsRequest) (*DriverDetailsResponse, error)
	// UpdateDriverDetails changes only the fields sent. Once the driver is
	// approved, a field already given only changes through support
	// (FAILED_PRECONDITION); an empty one can still be filled in.
	UpdateDriverDetails(context.Context, *UpdateDriverDetailsRequest) (*DriverDetailsResponse, error)
	// GetDriverPhoto: a short-lived link to the driver's approved profile
	// photo (the PROFILE_PHOTO document), for the driver and for services
	// (trip-service shows it to the rider). NOT_FOUND without one.
	GetDriverPhoto(context.Context, *GetDriverPhotoRequest) (*DriverPhotoResponse, error)
	// Name changes: an approved driver's name changes only after staff check
	// it against the approved ID (drivers.approve). One open request at a
	// time; a pending driver just edits the profile.
	RequestNameChange(context.Context, *RequestNameChangeRequest) (*NameChangeResponse, error)
	ListNameChanges(context.Context, *ListNameChangesRequest) (*ListNameChangesResponse, error)
	// The review queue, oldest first. Needs drivers.read.
	ListPendingNameChanges(context.Context, *ListPendingNameChangesRequest) (*ListNameChangesResponse, error)
	ApproveNameChange(context.Context, *ApproveNameChangeRequest) (*NameChangeResponse, error)
	RejectNameChange(context.Context, *RejectNameChangeRequest) (*NameChangeResponse, error)
	mustEmbedUnimplementedDriverServiceServer()
}

